package com.digitalbase.ticketing.controller;import com.digitalbase.ticketing.dto.AssignTicketRequest;import com.digitalbase.ticketing.dto.CreateTicketRequest;import com.digitalbase.ticketing.dto.TicketResponse;import com.digitalbase.ticketing.service.TicketService;import lombok.RequiredArgsConstructor;import org.springframework.http.MediaType;import org.springframework.http.ResponseEntity;import org.springframework.security.access.prepost.PreAuthorize; // ဤ Package ကို Import လုပ်ပါimport org.springframework.web.bind.annotation.*;import java.security.Principal;@RestController@RequestMapping("/api/tickets")@RequiredArgsConstructorpublic class TicketController {    private final TicketService ticketService;    // မည်သည့် Role မဆို Login ဝင်ထားပါက (Authenticated ဖြစ်ပါက) အသုံးပြုခွင့်ရှိသည်    @PostMapping(consumes = MediaType.MULTIPART_FORM_DATA_VALUE)    @PreAuthorize("isAuthenticated()") // (Optional) Login ဝင်ထားရန်သာလိုကြောင်း သတ်မှတ်ခြင်း    public ResponseEntity<TicketResponse> createTicket(            @ModelAttribute CreateTicketRequest request,            Principal principal) {        String userEmail = principal.getName();        TicketResponse ticket = ticketService.createTicket(request, userEmail);        return ResponseEntity.ok(ticket);    }    // ၁။ Ticket ကို Review အဆင့်သို့ ပြောင်းရန် API (Admin သီးသန့်)    @PreAuthorize("hasRole('ADMIN')") // <--- ဤနေရာတွင် Role ကန့်သတ်ချက် အသစ်ထည့်ပါသည်    @PutMapping("/{ticketId}/review")    public ResponseEntity<TicketResponse> reviewTicket(            @PathVariable Long ticketId,            Principal principal) {        String adminEmail = principal.getName();        TicketResponse response = ticketService.reviewTicket(ticketId, adminEmail);        return ResponseEntity.ok(response);    }    // ၂။ Developer ထံသို့ Assign ချပေးမည့် API (Admin သီးသန့်)    @PreAuthorize("hasRole('ADMIN')") // <--- ဤနေရာတွင် Role ကန့်သတ်ချက် အသစ်ထည့်ပါသည်    @PutMapping("/{ticketId}/assign")    public ResponseEntity<TicketResponse> assignTicket(            @PathVariable Long ticketId,            @RequestBody AssignTicketRequest request,            Principal principal) {        String adminEmail = principal.getName();        TicketResponse response = ticketService.assignTicket(ticketId, request, adminEmail);        return ResponseEntity.ok(response);    }}